-- Runs only inside the verifier's rollback subtransaction. Existing accounts,
-- sessions and vehicle registrations are used; none are fabricated or refreshed.
DO $checks$ DECLARE sid uuid;fresh uuid;cs text;uid text;vehicle text;oldqr text;r text;r2 text;batch text;newqr text;ord text;ful text;product text;rev integer;req uuid;payload jsonb;result jsonb;denied boolean;hash text;BEGIN
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND (p.proname LIKE 'admin_replacement_%' OR p.proname LIKE 'replacement_%' OR p.proname LIKE 'customer_replacement_%' OR p.proname IN ('customer_request_replacement','customer_activate_replacement','admin_request_replacement_export')) AND (prosecdef OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE'))) THEN RAISE EXCEPTION 'PUBLIC_REPLACEMENT_RPC';END IF;
 IF has_table_privilege('authenticated','public.replacement_requests','INSERT') OR has_table_privilege('anon','public.admin_replacement_events','SELECT') OR has_table_privilege('authenticated','public.qr_reservations','INSERT') THEN RAISE EXCEPTION 'PUBLIC_REPLACEMENT_WRITE';END IF;
 denied:=false;BEGIN PERFORM public.admin_replacement_command(NULL,NULL,'approve',0,'{}','Unauthorized command test',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='ADMIN_REQUIRED';END;IF NOT denied THEN RAISE EXCEPTION 'ADMIN_AUTH_BYPASS';END IF;
 denied:=false;BEGIN PERFORM public.customer_request_replacement(NULL,NULL,'DAMAGED','Unauthorized request test',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='VERIFIED_OWNER_REQUIRED';END;IF NOT denied THEN RAISE EXCEPTION 'CUSTOMER_AUTH_BYPASS';END IF;
 SELECT s.id INTO sid FROM public.admin_sessions s JOIN public.admin_users a ON a.id=s.admin_id WHERE s.revoked_at IS NULL AND s.expires_at>now() AND s.created_at>now()-interval '4 hours' AND s.email_verified_at IS NOT NULL AND a.status='ACTIVE' AND a.role IN ('SUPER_ADMIN','OPS_ADMIN') ORDER BY s.created_at DESC LIMIT 1;
 IF sid IS NULL THEN RAISE EXCEPTION 'REAL_ADMIN_SESSION_REQUIRED';END IF;
 PERFORM public.admin_replacement_list(sid);PERFORM public.admin_replacement_summary(sid);
 SELECT s.id::text,u.id::text,v.id,q.id INTO cs,uid,vehicle,oldqr FROM public.sessions s JOIN public.users u ON u.id=s.user_id JOIN public.qr_assignments a ON a.user_id=u.id::text AND a.ended_at IS NULL JOIN public.vehicles v ON v.id=a.vehicle_id AND v.user_id=u.id::text AND v.status='ACTIVE' JOIN public.qr_stickers q ON q.id=a.qr_id AND q.status='ACTIVATED' WHERE s.revoked_at IS NULL AND s.expires_at>now() AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM public.auth_identities ai WHERE ai.user_id=u.id AND ai.provider='PHONE' AND ai.provider_user_id=u.primary_phone AND ai.verified_at IS NOT NULL) AND EXISTS(SELECT 1 FROM public.service_entitlements e WHERE e.qr_sticker_id=q.id AND e.user_id=u.id::text AND e.vehicle_id=v.id AND e.capability='REPLACEMENT_ELIGIBLE' AND e.status='ENABLED' AND (e.expires_at IS NULL OR e.expires_at>now())) AND NOT EXISTS(SELECT 1 FROM public.replacement_requests x WHERE x.vehicle_id=v.id AND x.status NOT IN ('COMPLETED','REJECTED','CANCELLED')) ORDER BY s.created_at DESC LIMIT 1;
 IF cs IS NULL THEN RAISE EXCEPTION 'REAL_ELIGIBLE_OWNER_SESSION_REQUIRED';END IF;
 r:=public.customer_request_replacement(cs,oldqr,'DAMAGED','Rollback-only replacement verification',gen_random_uuid());
 IF public.customer_request_replacement(cs,oldqr,'DAMAGED','Rollback-only retry',gen_random_uuid())<>r THEN RAISE EXCEPTION 'DUPLICATE_REQUEST';END IF;
 IF (SELECT count(*) FROM public.notification_intents WHERE dedupe_key='replacement-request:'||r)<>1 OR (SELECT count(*) FROM public.notifications WHERE action_target='/qr/replace/'||r AND event_type='QR_REPLACEMENT_REQUESTED')<>1 THEN RAISE EXCEPTION 'REQUEST_NOTIFICATION_NOT_IDEMPOTENT';END IF;
 IF NOT public.replacement_owner_eligible(r) THEN RAISE EXCEPTION 'OWNER_CHECK';END IF;
 result:=public.admin_replacement_detail(sid,r);IF result::text LIKE '%secret_hash%' OR result::text LIKE '%primary_phone%' OR result::text LIKE '%shipping_address%' THEN RAISE EXCEPTION 'PROJECTION_SECRET_LEAK';END IF;
 PERFORM public.admin_replacement_options(sid,r);PERFORM public.admin_replacement_history(sid,r,'timeline');PERFORM public.admin_replacement_history(sid,r,'audit');PERFORM public.admin_replacement_history(sid,r,'lineage');PERFORM public.customer_replacement_context(cs,r);
 UPDATE public.replacement_requests SET requested_at='2026-10-12T18:30:00Z' WHERE id=r;
 result:=public.replacement_query('{"from":"2026-10-13","to":"2026-10-13"}',NULL,51,ARRAY[r]);IF jsonb_array_length(result)<>1 THEN RAISE EXCEPTION 'IST_LOWER_BOUNDARY';END IF;
 result:=public.replacement_query('{"from":"2026-10-12","to":"2026-10-12"}',NULL,51,ARRAY[r]);IF jsonb_array_length(result)<>0 THEN RAISE EXCEPTION 'IST_UPPER_BOUNDARY';END IF;
 denied:=false;BEGIN UPDATE public.replacement_requests SET user_id='invalid-owner' WHERE id=r;EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='IMMUTABLE_REPLACEMENT_IDENTITY';END;IF NOT denied THEN RAISE EXCEPTION 'OWNER_MUTABLE';END IF;
 batch:='rollback_'||gen_random_uuid()::text;newqr:='rollback_'||gen_random_uuid()::text;ord:='rollback_'||gen_random_uuid()::text;ful:='rollback_'||gen_random_uuid()::text;hash:=gen_random_uuid()::text;
 SELECT id INTO product FROM public.products WHERE product_type='REPLACEMENT_STICKER' AND status='ACTIVE' LIMIT 1;IF product IS NULL THEN RAISE EXCEPTION 'CONFIGURED_REPLACEMENT_PRODUCT_REQUIRED';END IF;
 INSERT INTO public.qr_batches(id,reference_code,quantity,status,inventory_channel,printed_at) VALUES(batch,'ROLLBACK-'||gen_random_uuid()::text,1,'PRINTED','ONLINE_SYSTEM',now());
 INSERT INTO public.qr_stickers(id,public_id,visible_code,batch_id,status,lifecycle_state) VALUES(newqr,gen_random_uuid()::text,'VS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),batch,'PRINTED','PRINTED');
 INSERT INTO public.qr_activation_secrets(id,qr_id,secret_hash,hash_version) VALUES('rollback_'||gen_random_uuid()::text,newqr,hash,'v1');
 IF NOT public.replacement_inventory_eligible(newqr) THEN RAISE EXCEPTION 'ELIGIBLE_STOCK';END IF;
 INSERT INTO public.orders(id,user_id,vehicle_id,order_number,status,payment_state,total_minor,paid_at,shipping_name,shipping_phone,shipping_address_line1,shipping_city,shipping_state,shipping_postal_code) VALUES(ord,uid,vehicle,'ROLLBACK-'||gen_random_uuid()::text,'PAID','PAID',19900,now(),'Rollback-only shipment','9000000000','Rollback-only address','Test','Test','500001');
 INSERT INTO public.order_items(id,order_id,product_id,product_name,quantity,total_price_minor) VALUES('rollback_'||gen_random_uuid()::text,ord,product,'Rollback-only replacement kit',1,19900);
 IF NOT public.replacement_order_eligible(r,ord) THEN RAISE EXCEPTION 'PAID_GATE';END IF;
 UPDATE public.orders SET payment_state='PROCESSING' WHERE id=ord;IF public.replacement_order_eligible(r,ord) THEN RAISE EXCEPTION 'PAYMENT_PENDING_ACCEPTED';END IF;UPDATE public.orders SET payment_state='PAID' WHERE id=ord;
 SELECT s.id INTO fresh FROM public.admin_sessions s JOIN public.admin_users a ON a.id=s.admin_id WHERE s.revoked_at IS NULL AND s.expires_at>now() AND s.created_at>now()-interval '4 hours' AND s.email_verified_at IS NOT NULL AND s.step_up_at>now()-interval '10 minutes' AND a.status='ACTIVE' AND a.role IN ('SUPER_ADMIN','OPS_ADMIN') ORDER BY s.step_up_at DESC LIMIT 1;
 IF fresh IS NULL THEN denied:=false;BEGIN PERFORM public.admin_replacement_command(sid,r,'approve',(SELECT revision FROM public.replacement_requests WHERE id=r),'{"riskAcknowledged":true}','Rollback-only expired email verification',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='ADMIN_REQUIRED';END;IF NOT denied THEN RAISE EXCEPTION 'FRESH_VERIFICATION_BYPASS';END IF;END IF;
 IF fresh IS NOT NULL THEN
 SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;req:=gen_random_uuid();payload:='{"riskAcknowledged":true}';PERFORM public.admin_replacement_command(fresh,r,'approve',rev,payload,'Rollback-only eligibility approval',req);PERFORM public.admin_replacement_command(fresh,r,'approve',rev,payload,'Rollback-only eligibility approval',req);
 denied:=false;BEGIN PERFORM public.admin_replacement_command(fresh,r,'allocate',rev,jsonb_build_object('order',ord,'batch',batch),'Rollback-only stale allocation',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='STATE_CHANGED';END;IF NOT denied THEN RAISE EXCEPTION 'STALE_REVISION_ACCEPTED';END IF;
 SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;UPDATE public.orders SET payment_state='PENDING' WHERE id=ord;
 denied:=false;BEGIN PERFORM public.admin_replacement_command(fresh,r,'allocate',rev,jsonb_build_object('order',ord,'batch',batch),'Rollback-only pending payment',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='INVALID_PAID_ORDER';END;IF NOT denied THEN RAISE EXCEPTION 'ALLOCATION_PAYMENT_BYPASS';END IF;UPDATE public.orders SET payment_state='PAID' WHERE id=ord;
 req:=gen_random_uuid();payload:=jsonb_build_object('order',ord,'batch',batch);PERFORM public.admin_replacement_command(fresh,r,'allocate',rev,payload,'Rollback-only paid allocation',req);PERFORM public.admin_replacement_command(fresh,r,'allocate',rev,payload,'Rollback-only paid allocation',req);
 SELECT fulfilment_id INTO ful FROM public.replacement_requests WHERE id=r;
 IF public.replacement_inventory_eligible(newqr) OR (SELECT status FROM public.qr_stickers WHERE id=newqr)<>'ALLOCATED' OR NOT EXISTS(SELECT 1 FROM public.qr_assignments WHERE qr_id=oldqr AND ended_at IS NULL) OR EXISTS(SELECT 1 FROM public.qr_assignments WHERE qr_id=newqr AND ended_at IS NULL) THEN RAISE EXCEPTION 'ALLOCATION_ACTIVATES_SERVICE';END IF;
 SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;PERFORM public.admin_replacement_command(fresh,r,'retire',rev,'{}','Rollback-only deliberate retirement',gen_random_uuid());
 SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;PERFORM public.admin_replacement_command(fresh,r,'pack',rev,'{}','Rollback-only verified physical packing',gen_random_uuid());
 ELSE
 -- Validate customer handover guards independently when no fresh admin OTP exists.
 INSERT INTO public.fulfilments(id,order_id,user_id,type,status) VALUES(ful,ord,uid,'REPLACEMENT_QR','PROCESSING');
 INSERT INTO public.qr_reservations(id,qr_sticker_id,fulfilment_id,order_id,status) VALUES('rollback_'||gen_random_uuid()::text,newqr,ful,ord,'RESERVED');
 UPDATE public.qr_stickers SET status='ALLOCATED',lifecycle_state='ALLOCATED' WHERE id=newqr;
 UPDATE public.replacement_requests SET status='MIGRATED',new_qr_sticker_id=newqr,order_id=ord,fulfilment_id=ful,retired_at=now(),approved_at=now() WHERE id=r;
 INSERT INTO public.replacement_entitlement_snapshots(replacement_id,capability,expires_at,acquisition_source,original_order_id,verified_at) SELECT r,capability,expires_at,acquisition_source,order_id,coalesce(verified_at,now()) FROM public.service_entitlements WHERE qr_sticker_id=oldqr AND status='ENABLED';
 UPDATE public.qr_assignments SET ended_at=now(),is_current=0,end_reason='REPLACED' WHERE qr_id=oldqr AND ended_at IS NULL;
 UPDATE public.service_entitlements SET status='REVOKED' WHERE qr_sticker_id=oldqr AND status='ENABLED';
 UPDATE public.qr_stickers SET status='REPLACED',lifecycle_state='REPLACED',replaced_by_qr_id=newqr WHERE id=oldqr;
 INSERT INTO public.sticker_replacements(id,replacement_request_id,old_qr_sticker_id,new_qr_sticker_id,vehicle_id,reason,migrated_at) VALUES('rollback_'||gen_random_uuid()::text,r,oldqr,newqr,vehicle,'DAMAGED',now());
 END IF;
 denied:=false;BEGIN PERFORM public.customer_activate_replacement(cs,r,hash);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='INVALID_ACTIVATION';END;IF NOT denied THEN RAISE EXCEPTION 'DELIVERY_BYPASS';END IF;
 INSERT INTO public.shipments(id,fulfilment_id,order_id,user_id,status,shipped_at,delivered_at) VALUES('rollback_'||gen_random_uuid()::text,ful,ord,uid,'DELIVERED',now(),now());
 IF fresh IS NOT NULL THEN SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;PERFORM public.admin_replacement_command(fresh,r,'sync_shipment',rev,'{}','Rollback-only carrier status sync',gen_random_uuid());END IF;
 denied:=false;BEGIN PERFORM public.customer_activate_replacement(cs,r,'wrong-hash');EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='INVALID_ACTIVATION';END;IF NOT denied THEN RAISE EXCEPTION 'PROOF_BYPASS';END IF;
 UPDATE public.orders SET payment_state='REFUNDED' WHERE id=ord;denied:=false;BEGIN PERFORM public.customer_activate_replacement(cs,r,hash);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='INVALID_ACTIVATION';END;IF NOT denied THEN RAISE EXCEPTION 'REFUND_ACTIVATION_BYPASS';END IF;UPDATE public.orders SET payment_state='PAID' WHERE id=ord;
 FOR rev IN 1..5 LOOP IF public.customer_replacement_proof_attempt(cs,r) IS NULL THEN RAISE EXCEPTION 'ATTEMPT_BUDGET';END IF;END LOOP;
 IF public.customer_replacement_proof_attempt(cs,r) IS NOT NULL THEN RAISE EXCEPTION 'ATTEMPT_LIMIT_BYPASS';END IF;
 -- Restore only rollback-only stock to exercise the valid private handover RPC.
 UPDATE public.qr_activation_secrets SET locked_until=NULL,failed_attempts=0 WHERE qr_id=newqr;
 PERFORM public.customer_activate_replacement(cs,r,hash);PERFORM public.customer_activate_replacement(cs,r,hash);
 IF (SELECT count(*) FROM public.qr_assignments WHERE vehicle_id=vehicle AND ended_at IS NULL)<>1 OR (SELECT status FROM public.qr_stickers WHERE id=oldqr)<>'REPLACED' OR EXISTS(SELECT 1 FROM public.service_entitlements WHERE qr_sticker_id=oldqr AND status='ENABLED') OR (SELECT status FROM public.qr_stickers WHERE id=newqr)<>'ACTIVATED' OR (SELECT consumed_at FROM public.qr_activation_secrets WHERE qr_id=newqr) IS NULL THEN RAISE EXCEPTION 'DOUBLE_ACTIVE_IDENTITY';END IF;
 IF (SELECT replaced_by_qr_id FROM public.qr_stickers WHERE id=oldqr) IS NOT NULL THEN RAISE EXCEPTION 'PUBLIC_REPLACEMENT_DISCLOSURE';END IF;
 IF EXISTS(SELECT 1 FROM public.service_entitlements e JOIN public.replacement_entitlement_snapshots snap ON snap.replacement_id=r AND snap.capability=e.capability WHERE e.qr_sticker_id=newqr AND (e.expires_at IS DISTINCT FROM snap.expires_at OR e.order_id<>ord OR e.acquisition_source<>'ONLINE_PURCHASE')) THEN RAISE EXCEPTION 'ENTITLEMENT_ESCALATION';END IF;
 denied:=false;BEGIN DELETE FROM public.sticker_replacements WHERE replacement_request_id=r;EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'LINEAGE_MUTABLE';END IF;
 IF fresh IS NOT NULL THEN SELECT revision INTO rev FROM public.replacement_requests WHERE id=r;PERFORM public.admin_replacement_command(fresh,r,'close',rev,'{}','Rollback-only completed identity closure',gen_random_uuid());IF (SELECT status FROM public.replacement_requests WHERE id=r)<>'COMPLETED' THEN RAISE EXCEPTION 'CLOSURE_FAILED';END IF;END IF;
END;$checks$;
